window.search = Object.assign(window.search, JSON.parse('{"doc_urls": ["introduction.html#introduction", "examples/hello-world.html#hello-world", "examples/hello-world.html#cargotoml", "examples/hello-world.html#srclibrs", "examples/hello-world.html#indexjs", "examples/hello-world.html#webpack-specific-files", "examples/console-log.html#consolelog", "examples/console-log.html#srclibrs", "examples/import-js.html#importing-non-browser-js", "reference/attributes/on-js-imports/index.html#wasm_bindgen-on-javascript-imports"], "index": {"documentStore": {"docs": {"0": {"id": "0", "title": "Introduction", "body": "This book is about wasm-bindgen, a Rust library and CLI tool that facilitate\\nhigh-level interactions between Wasm modules and JavaScript. The wasm-bindgen\\ntool and crate are only one part of the Rust and WebAssembly\\necosystem. If you’re not familiar already with wasm-bindgen it’s\\nrecommended to start by reading the Game of Life tutorial. If you’re\\ncurious about wasm-pack, you can find that documentation here\\n(including the current installer; older rustwasm.github.io/wasm-pack/installer/ URLs are", "breadcrumbs": "Introduction » Introduction"}, "1": {"id": "1", "title": "Hello, World!", "body": "View full source code or view the compiled example online This is the “Hello, world!” example of #[wasm_bindgen] showing how to set up\\na project, export a function to JS, call it from JS, and then call the alert\\nfunction in Rust.", "breadcrumbs": "Examples » Hello, World! » Hello, World!"}, "2": {"id": "2", "title": "Cargo.toml", "body": "The Cargo.toml lists the wasm-bindgen crate as a dependency. Also of note is the crate-type = [\\"cdylib\\"] which is largely used for wasm\\nfinal artifacts today. [package]\\nauthors = [\\"The wasm-bindgen Developers\\"]\\nedition = \\"2021\\"\\nname = \\"hello_world\\"\\npublish = false\\nversion = \\"0.0.0\\" [lib]\\ncrate-type = [\\"cdylib\\"] [dependencies]\\nwasm-bindgen = { path = \\"../../\\" } [lints]\\nworkspace = true", "breadcrumbs": "Examples » Hello, World! » Cargo.toml"}, "3": {"id": "3", "title": "src/lib.rs", "body": "Here we define our Rust entry point along with calling the alert function. #![allow(unused)] fn main() {\\nuse wasm_bindgen::prelude::*; #[wasm_bindgen]\\nextern \\"C\\" { fn alert(s: &str);\\n} #[wasm_bindgen]\\npub fn greet(name: &str) { alert(&format!(\\"Hello, {name}!\\"));\\n} }", "breadcrumbs": "Examples » Hello, World! » src/lib.rs"}, "4": {"id": "4", "title": "index.js", "body": "Our JS entry point is quite small! import { greet } from \'./pkg\'; greet(\'World\');", "breadcrumbs": "Examples » Hello, World! » index.js"}, "5": {"id": "5", "title": "Webpack-specific files", "body": "Note: Webpack is required for this example, and if you’re interested\\nin options that don’t use a JS bundler see other examples. And finally here’s the Webpack configuration and package.json for this\\nproject: webpack.config.js const path = require(\'path\');\\nconst HtmlWebpackPlugin = require(\'html-webpack-plugin\');\\nconst webpack = require(\'webpack\');\\nconst WasmPackPlugin = require(\\"@wasm-tool/wasm-pack-plugin\\"); module.exports = { entry: \'./index.js\', output: { path: path.resolve(__dirname, \'..\', \'", "breadcrumbs": "Examples » Hello, World! » Webpack-specific files"}, "6": {"id": "6", "title": "console.log", "body": "View full source code or view the compiled example online This example shows off how to use console.log in a variety of ways, all the\\nway from bare-bones usage to a println!-like macro with web_sys.", "breadcrumbs": "Examples » Using console.log » console.log"}, "7": {"id": "7", "title": "src/lib.rs", "body": "#![allow(unused)] fn main() {\\nuse wasm_bindgen::prelude::*; #[wasm_bindgen(start)]\\nfn run() { bare_bones(); using_a_macro(); using_web_sys();\\n} // First up let\'s take a look of binding `console.log` manually, without the\\n// help of `web_sys`. Here we\'re writing the `#[wasm_bindgen]` annotations\\n// manually ourselves, and the correctness of our program relies on the\\n// correctness of these annotations! #[wasm_bindgen]\\nextern \\"C\\" { // Use `js_namespace` here to bind `console.log(..)` instead of ju", "breadcrumbs": "Examples » Using console.log » src/lib.rs"}, "8": {"id": "8", "title": "Importing non-browser JS", "body": "View full source code or view the compiled example online The #[wasm_bindgen] attribute can be used on extern \\"C\\" { .. } blocks to import\\nfunctionality from JS. This is how the js-sys and the web-sys crates are\\nbuilt, but you can also use it in your own crate! For example if you’re working with this JS file: // defined-in-js.js\\nexport function name() { return \'Rust\';\\n} export class MyClass { constructor() { this._number = 42; } get number() { return this._number; } set number(n) { return this._n", "breadcrumbs": "Examples » Importing functions from JS » Importing non-browser JS"}, "9": {"id": "9", "title": "#[wasm_bindgen] on JavaScript Imports", "body": "This section enumerates the attributes available for customizing bindings for\\nJavaScript functions and classes imported into Rust within an extern \\"C\\" { ... }\\nblock.", "breadcrumbs": "Reference » #[wasm_bindgen] Attributes » On JavaScript Imports » #[wasm_bindgen] on JavaScript Imports"}}, "docInfo": {}, "length": 10, "save": true}, "fields": ["title", "body", "breadcrumbs"], "index": {}, "lang": "English", "pipeline": ["trimmer", "stopWordFilter", "stemmer"], "ref": "id", "version": "0.9.5"}, "results_options": {"limit_results": 30, "teaser_word_count": 30}, "search_options": {"bool": "OR", "expand": true, "fields": {"body": {"boost": 1}, "breadcrumbs": {"boost": 1}, "title": {"boost": 2}}}}'));